import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.DefaultHandler;
import com.sun.net.httpserver.*;

public class ConfigImportService {
    private static final Map<String, String> configStore = new HashMap<>();
    private static final Set<String> BLOCKED_TAGS = Set.of("script", "iframe", "object");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/config/import", ConfigImportService::handleImport);
        server.createContext("/api/config/list", ConfigImportService::handleList);
        server.setExecutor(null);
        server.start();
        System.out.println("Config import service running on :8080");
    }

    static void handleImport(HttpExchange exchange) throws IOException {
        if (!"POST".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, 0);
            exchange.close();
            return;
        }
        String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
        if (contentType == null || !contentType.contains("xml")) {
            sendResponse(exchange, 400, "Content-Type must be application/xml");
            return;
        }
        // Rate limiting: max 50 configs
        if (configStore.size() > 50) {
            sendResponse(exchange, 429, "Config store full");
            return;
        }
        try {
            byte[] body = exchange.getRequestBody().readAllBytes();
            if (body.length > 10240) {
                sendResponse(exchange, 413, "Payload too large (max 10KB)");
                return;
            }
            // Basic content validation - reject obviously malicious patterns
            String bodyStr = new String(body, "UTF-8");
            for (String tag : BLOCKED_TAGS) {
                if (bodyStr.toLowerCase().contains("<" + tag)) {
                    sendResponse(exchange, 400, "Blocked element: " + tag);
                    return;
                }
            }
            // Parse the XML configuration
            Map<String, String> parsed = parseConfigXml(body);
            configStore.putAll(parsed);
            sendResponse(exchange, 200, "Imported " + parsed.size() + " config entries");
        } catch (Exception e) {
            sendResponse(exchange, 500, "Parse error: " + e.getMessage());
        }
    }

    static Map<String, String> parseConfigXml(byte[] xmlData) throws Exception {
        Map<String, String> result = new HashMap<>();
        SAXParserFactory factory = SAXParserFactory.newInstance();
        // Disable DTD loading for security
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        SAXParser parser = factory.newSAXParser();
        parser.parse(new ByteArrayInputStream(xmlData), new DefaultHandler() {
            String currentKey = null;
            StringBuilder currentValue = new StringBuilder();
            public void startElement(String uri, String localName, String qName, Attributes attrs) {
                if ("entry".equals(qName)) {
                    currentKey = attrs.getValue("key");
                    currentValue.setLength(0);
                }
            }
            public void characters(char[] ch, int start, int length) {
                if (currentKey != null) currentValue.append(ch, start, length);
            }
            public void endElement(String uri, String localName, String qName) {
                if ("entry".equals(qName) && currentKey != null) {
                    result.put(currentKey, currentValue.toString());
                    currentKey = null;
                }
            }
        });
        return result;
    }

    static void handleList(HttpExchange exchange) throws IOException {
        StringBuilder sb = new StringBuilder("{\n");
        for (Map.Entry<String, String> e : configStore.entrySet()) {
            sb.append("  \"").append(e.getKey()).append("\": \"").append(e.getValue()).append("\",\n");
        }
        sb.append("}");
        sendResponse(exchange, 200, sb.toString());
    }

    static void sendResponse(HttpExchange exchange, int code, String body) throws IOException {
        byte[] resp = body.getBytes("UTF-8");
        exchange.sendResponseHeaders(code, resp.length);
        exchange.getResponseBody().write(resp);
        exchange.close();
    }
}
